+package utils
+
+import (
+	"path/filepath"
+	"testing"
+)
+
+func TestIsDirReadable(t *testing.T) {
+	path := t.TempDir()
+	readable, err := IsDirReadable(path)
+	if err != nil || !readable {
+		t.Fatalf("expected readable directory, got readable=%v, err=%v", readable, err)
+	}
+
+	readable, err = IsDirReadable(filepath.Join(path, "missing"))
+	if err == nil || readable {
+		t.Fatalf("expected open error, got readable=%v, err=%v", readable, err)
+	}
+}
